mapper.select:
SELECT 
FROM crm_customer
WHERE tenant_id = #{tenantId}
  AND active_name_key = #{activeNameKey}
  AND operating_status != '已归档'
  AND del_flag = '0'

SELECT 
FROM crm_customer
WHERE tenant_id = #{tenantId}
  AND primary_owner_id = #{primaryOwnerId}
  AND del_flag = '0'
ORDER BY create_time DESC

SELECT 
FROM crm_customer
WHERE tenant_id = #{tenantId}
  AND owner_dept_id = #{ownerDeptId}
  AND del_flag = '0'
ORDER BY create_time DESC

SELECT 
FROM crm_customer
WHERE tenant_id = #{tenantId} AND del_flag = '0'

    AND name LIKE CONCAT('%', #{query.name}, '%')


    AND operating_status = #{query.operatingStatus}


    AND lifecycle_stage = #{query.lifecycleStage}


    AND primary_owner_id = #{query.primaryOwnerId}


    AND owner_dept_id = #{query.ownerDeptId}


    AND importance = #{query.importance}


    AND source = #{query.source}


    AND industry = #{query.industry}

ORDER BY create_time DESC
